package com.rekluzlabs.makokolorize.ui.componentsimport androidx.compose.animation.core.animateFloatAsStateimport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.heightimport androidx.compose.material3.LinearProgressIndicatorimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.runtime.getValueimport androidx.compose.ui.Modifierimport androidx.compose.ui.unit.dpimport androidx.compose.ui.unit.sp@Composablefun AppProgressIndicator(    progress: Float,    modifier: Modifier = Modifier) {    val animatedProgress by animateFloatAsState(        targetValue = progress,        label = "progress"    )    Column(modifier = modifier.fillMaxWidth()) {        LinearProgressIndicator(            progress = { animatedProgress },            modifier = Modifier                .fillMaxWidth()                .height(8.dp)        )        Spacer(modifier = Modifier.height(4.dp))        Text(            text = "${(progress * 100).toInt()}%",            fontSize = 14.sp        )    }}